import{_ as a,c as n,a as p,o as r}from"./app-CJ0S7cE_.js";const i={};function d(c,e){return r(),n("div",null,e[0]||(e[0]=[p('<blockquote><p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。 欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p></blockquote><h1 id="_2026-11-12-资讯日报" tabindex="-1"><a class="header-anchor" href="#_2026-11-12-资讯日报"><span>2026-11-12 资讯日报</span></a></h1><h2 id="新闻资讯" tabindex="-1"><a class="header-anchor" href="#新闻资讯"><span>新闻资讯</span></a></h2><h3 id="芯片厂商cerebras上市半年股价跌77" tabindex="-1"><a class="header-anchor" href="#芯片厂商cerebras上市半年股价跌77"><span>芯片厂商Cerebras上市半年股价跌77%</span></a></h3><p>芯片公司 Cerebras 上市半年股价暴跌近77%。其核心硬件销售连续两季下滑，云服务占比升至70%，二季度现金流出达营收的2.65倍。</p><p>云服务收入占比升至70%，硬件销售连续两季下滑</p><p>推理速度近英伟达15倍，但Token单价仅高25%</p><p>毛利率降至40.6%，二季度现金净流出4.77亿美元<a href="https://mp.weixin.qq.com/s?__biz=MzkyNTY1MjE2OA==&amp;chksm=c03c68fa681531d5911e630747da72cf83a036357647f6457a8e6ac4000c85cb0207680729ed&amp;idx=1&amp;mid=2247494678&amp;sn=0fdac24f7e8fc869d8dbb5bee794087a" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="菜鸟开放仓库训练机器人-推出海三日达" tabindex="-1"><a class="header-anchor" href="#菜鸟开放仓库训练机器人-推出海三日达"><span>菜鸟开放仓库训练机器人，推出海三日达</span></a></h3><p>菜鸟宣布开放全球真实仓库作为训练集，提供上百种验证场景加速具身机器人落地；同时推出硬科技出海服务，支持算力与机器人跨境交付。</p><p>将物流拆为短程泛化、中程精准与长程策略三阶段</p><p>部分筛选场景国内投资回收期预计 1 至 2 年</p><p>AI 辅助配仓达 96%，消费级机器人占菜鸟收入 10%<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=85a764c8c329b9b0308644ccaeb46d19c9f3ff9bf5ee1a938a24091990074e17b6924ab61219&amp;idx=1&amp;mid=2651073583&amp;sn=83cc6c943216d42d020d383eb4e64136" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="张一鸣称字节追上openai至少到2029年" tabindex="-1"><a class="header-anchor" href="#张一鸣称字节追上openai至少到2029年"><span>张一鸣称字节追上OpenAI至少到2029年</span></a></h3><p>彭博社称字节跳动计划数周内推出类似 Meta Muse 的个人智能体。张一鸣在内部会议表示，字节有能力进入最前沿，但至少要到2029或2030年才能追上 OpenAI。</p><p>智能体项目：内部代号Spell，将结合豆包产品推出</p><p>研发路线：坚持自主研发不依赖蒸馏，数据规模差距大</p><p>业务投入：计划投入最高700亿美元，团队约千人<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzgzMjA3NA==&amp;chksm=8615ff7d554da01498efed8abf320107a007e902ba1508caadaeb5374242cd980afb4c9a78c9&amp;idx=1&amp;mid=2650779740&amp;sn=d6b21dc9a7311f2e4b88aa562a73a2da" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="ai数据公司mercor估值达200亿美元" tabindex="-1"><a class="header-anchor" href="#ai数据公司mercor估值达200亿美元"><span>AI数据公司Mercor估值达200亿美元</span></a></h3><p>为前沿模型提供训练数据与评测服务的 Mercor 获 7.5 亿美元 D 轮融资，英伟达等参投，估值达 200 亿美元。该公司年化收入已突破 20 亿美元，OpenAI 为其客户。</p><p>业务模式：连接超500万行业专家提供数据与评估</p><p>推理支出：运行AI模型的推理花费已达员工薪资3倍</p><p>团队背景：三位00后创始人于19岁辍学创办<a href="https://mp.weixin.qq.com/s?__biz=MzA4MTQ4NjQzMw==&amp;chksm=85c32f0f44497920d240d2f227d43820d3d5028751ab43e3a557745c42ebe160e53fe3bf040b&amp;idx=3&amp;mid=2652813815&amp;sn=798ca7e7696bb294d5ec5b3bd38e068c" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="科技报告-美工程师招聘腰斩pm增56" tabindex="-1"><a class="header-anchor" href="#科技报告-美工程师招聘腰斩pm增56"><span>科技报告：美工程师招聘腰斩PM增56%</span></a></h3><p>Lenny Rachitsky 报告显示，美国过去 12 个月软件工程师招聘仅 11.3 万人，不到 2022 年峰值的一半；开放 PM 岗位较 2023 年初增长 56%。</p><p>设计与用研：全球开放设计岗降至记录最低，用研招聘跌66%</p><p>技能转变：LLM成PM和工程最高频技能，Claude进前三</p><p>办公趋势：岗位加速向湾区集中，远程岗位比例降至14%<a href="https://mp.weixin.qq.com/s?__biz=MzA5MTIxNTY4MQ==&amp;chksm=86b3dd2ec67855a5f836429cc6b005f2af06247a8206d18b6c0ececdaf183c94f806a45b44f8&amp;idx=1&amp;mid=2461161945&amp;sn=918ed0ccef5abcf2d0e0559622136906" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="claude-仅用-3-天自主移植-amd-芯片内核" tabindex="-1"><a class="header-anchor" href="#claude-仅用-3-天自主移植-amd-芯片内核"><span>Claude 仅用 3 天自主移植 AMD 芯片内核</span></a></h3><p>Anthropic 披露，其模型仅用约三天自主重写底层计算内核，跑通 AMD 芯片推理。以往此类迁移通常需要团队攻坚 6 到 12 个月。</p><p>在 MI355X 上跑通提示词处理阶段，未覆盖完整系统</p><p>AMD 拟向 Anthropic 投资最高 50 亿美元</p><p>已在英伟达、AMD、TPU 与 Trainium 上混合运行<a href="https://mp.weixin.qq.com/s?__biz=MzU1NDA4NjU2MA==&amp;chksm=fac84dd93caa9971fa2105bd79c8f93a580f52f24931dbc6db09cdf425950892beb0ce0b55be&amp;idx=1&amp;mid=2247669362&amp;sn=e726dc471a1f3571e6699da8f0d0a717" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="阿里分拆芯片业务平头哥拟赴港上市" tabindex="-1"><a class="header-anchor" href="#阿里分拆芯片业务平头哥拟赴港上市"><span>阿里分拆芯片业务平头哥拟赴港上市</span></a></h3><p>阿里巴巴宣布向港交所提交分拆芯片子公司平头哥独立上市的申请，分拆后仍为其子公司。平头哥真武系列AI芯片累计出货达56万片，超60%芯片服务外部客户。</p><p>产品布局：覆盖算力、存储、网络芯片及超节点算力底座</p><p>分拆背景：阿里单季资本开支达676.78亿元需独立融资</p><p>客户规模：芯片已在金融、自动驾驶等行业超650家客户落地<a href="https://mp.weixin.qq.com/s?__biz=MzA3NzMxNTI1MQ==&amp;chksm=86144f7f64b71b0baa72f54c035d4276b0c4f61acfd082b4bff7461fc249fbb07612c33ff850&amp;idx=1&amp;mid=2649787329&amp;sn=37109056a479281336e0b662d8e8819a" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="产品应用" tabindex="-1"><a class="header-anchor" href="#产品应用"><span>产品应用</span></a></h2><h3 id="claude-fable-5-2提示词指南发布" tabindex="-1"><a class="header-anchor" href="#claude-fable-5-2提示词指南发布"><span>Claude Fable 5.2提示词指南发布</span></a></h3><p>Anthropic 官方发布 Claude Fable 5.2 提示词指南，详解推理强度档位选择、长任务提前中断等行为差异，并给出多套可直接套用的系统提示词模板。</p><p>加入持续推进提示词可将中途停下的会话减少约半数</p><p>明确由模型负责后，合并重复代码的比例升至约五成</p><p>默认high体现多数增益，medium以上无法用指令禁思考<a href="https://mp.weixin.qq.com/s?__biz=MzI5MDUyMDIxNA==&amp;chksm=edf67d3e38f5eaac12aa232830f1fb0851fed914667f0be7a038dcd8d144fcb296ca09896abf&amp;idx=2&amp;mid=2247720546&amp;sn=c5a73f6c88474917727913c111051e0d" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="腾讯上线元宝搜索并开放独立网页" tabindex="-1"><a class="header-anchor" href="#腾讯上线元宝搜索并开放独立网页"><span>腾讯上线元宝搜索并开放独立网页</span></a></h3><p>腾讯正式推出面向 C 端的元宝搜索，基于千亿级网页索引与大模型重构检索链路；目前已开放独立网站 so.qq.com，最新版 QQ 浏览器也支持切换使用。</p><p>内容源：接入微信公众号与视频号等腾讯生态</p><p>交互：顶部提供 AI 总结且支持多模态连续追问</p><p>商业化：广告不伪装成答案并减少连续检索打断<a href="https://mp.weixin.qq.com/s?__biz=Mzg2OTY2MzE2NA==&amp;chksm=cf92ee542d75f1659e5aeed661624e7448eafe60b0f12ebc6fb920ee41b33c85ac2f165650e4&amp;idx=2&amp;mid=2247502742&amp;sn=a7f9fc14e905d9ce043fee57bec82558" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="谷歌发布决策模型-百万输入-0-1-美元" tabindex="-1"><a class="header-anchor" href="#谷歌发布决策模型-百万输入-0-1-美元"><span>谷歌发布决策模型，百万输入 0.1 美元</span></a></h3><p>谷歌在 Google AI Studio 上线专做判断的决策模型 Gemini Decision 1，不逐字生成文本，单次请求可处理最多 1000 个问题，每百万输入 Token 仅 0.1 美元且输出免费。</p><p>任务支持：支持是非判断、最多255选1及打分，带置信度</p><p>评测表现：9项测试拿下7项第1，校准误差比GPT-6低65%</p><p>落地场景：用于Agent路由与安全检测，日常查询延迟降40%<a href="https://mp.weixin.qq.com/s?__biz=MzU1NDA4NjU2MA==&amp;chksm=fad9c5e576377b83c4056a0456dd1ec5866922454f39286f344e553b9c9a3ecc48f9d07efb47&amp;idx=1&amp;mid=2247669387&amp;sn=27454f9cc7f3e4c043e7f86f16e22580" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="即梦上线短剧工作室-视频每秒最低0-16元" tabindex="-1"><a class="header-anchor" href="#即梦上线短剧工作室-视频每秒最低0-16元"><span>即梦上线短剧工作室：视频每秒最低0.16元</span></a></h3><p>即梦上线短剧工作室，涵盖剧本生成、3D 导演台与分镜制作，视频生成每秒最低 0.16 元；实测制作一集 2 分钟短剧全流程花费约 101 元。</p><p>功能：整合短剧模型DreamScript、AI选角与运镜库</p><p>福利：所有用户可免费试用1次剧本创作与15秒视频生成<a href="https://mp.weixin.qq.com/s?__biz=MzkzOTY1MTM3NA==&amp;chksm=c36374ca9d3cac895014ca240f5fa2d70e5d87b1db0dd7f15006a0ba72b06e4356eed0ae7a74&amp;idx=1&amp;mid=2247487077&amp;sn=599a13dc14e7094cfe608897026f0f9d" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="腾讯发布buddy-one打通全家桶ai" tabindex="-1"><a class="header-anchor" href="#腾讯发布buddy-one打通全家桶ai"><span>腾讯发布Buddy One打通全家桶AI</span></a></h3><p>腾讯推出跨应用AI协同体系Buddy One，关联一个免费ID即可打通腾讯文档、会议、ima与网盘，提问时可跨应用检索并生成带来源引用的回答。</p><p>算力积分：多应用统一消耗Buddy One共享积分池</p><p>收费方案：基础检索免费，VIP连续包月700元</p><p>使用方式：更新WorkBuddy至5.9.0版本即可关联<a href="https://mp.weixin.qq.com/s?__biz=MzU2Njg0OTEyNQ==&amp;chksm=fd7eddafc5e2a121de3a731dcb8a45125247bff4ac76fc22aebd6d8587440ff33609406274a8&amp;idx=1&amp;mid=2247498062&amp;sn=84ab617deb2cf150678759b181180995" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="推荐文章" tabindex="-1"><a class="header-anchor" href="#推荐文章"><span>推荐文章</span></a></h2><h3 id="前meta工程师称ai写代码让系统变脆" tabindex="-1"><a class="header-anchor" href="#前meta工程师称ai写代码让系统变脆"><span>前Meta工程师称AI写代码让系统变脆</span></a></h3><p>一名在 Meta 把 100% 代码交给 AI 的工程师撰文称，AI 编程工具虽然提高了产出速度，但因测试太浅、过度复杂和工程师理解弱化，导致系统变脆且故障恢复变慢。</p><p>质量隐患：测试只测表面交互且代码过度复杂</p><p>维护困难：开发者看不懂代码库导致事故恢复变慢</p><p>盲区累积：未捕获的错误只有真实用户能碰到<a href="https://mp.weixin.qq.com/s?__biz=MzE5OTIyODc3OA==&amp;chksm=9716b43004ac6f2654eb7b6559198c812177a1c08ab5badf3e5c08bdb2258d669ee052f78cb6&amp;idx=3&amp;mid=2247525390&amp;sn=180b49b510ec64b566d94cbfe4205d53" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="开源动态" tabindex="-1"><a class="header-anchor" href="#开源动态"><span>开源动态</span></a></h2><h3 id="minimax开源h3-image-10秒出4k图" tabindex="-1"><a class="header-anchor" href="#minimax开源h3-image-10秒出4k图"><span>MiniMax开源H3-Image，10秒出4K图</span></a></h3><p>MiniMax正式发布图像生成模型H3-Image并开放权重，高速版可在10秒左右生成4K图像，耗时约为市面主流模型的五分之一，已上线海螺官网。</p><p>多图融合：最多支持16张参考图拆解重组，涵盖人物服装及版式骨架</p><p>中文排版：实测可准确生成含约100个汉字、步骤及数字单位的海报</p><p>专业任务：结合Agent可生成部件拆解机械爆炸图及工业设计三视图<a href="https://mp.weixin.qq.com/s?__biz=MzA4MTQ4NjQzMw==&amp;chksm=859f73b9682c70a701d0e3e3ebc876bf757f15d9cbddf6a91f5d98bfff6d5515a3ffaf4b7a63&amp;idx=1&amp;mid=2652813815&amp;sn=2b6a0855985ed9dbc638868c25ae320c" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="vllm-与-sglang-追平-deepinfer-性能" tabindex="-1"><a class="header-anchor" href="#vllm-与-sglang-追平-deepinfer-性能"><span>vLLM 与 SGLang 追平 DeepInfer 性能</span></a></h3><p>DeepSeek 开源线上推理框架 DeepInfer 后，vLLM 和 SGLang 宣布已在性能上追平。两家吸收了其数据格式与线上调度经验，算子层面并无新增。</p><p>引入上下文限流与缩容迁移规则，算子未有新增</p><p>DeepInfer 仅限特定硬件，社区框架支持多款芯片</p><p>单一模型机柜参考官方，多模型多硬件选社区框架<a href="https://mp.weixin.qq.com/s?__biz=MzI4MDYzNzg4Mw==&amp;chksm=ea387b72cf8c8b4632f1f26f6e37de377a8bd684765469edc8ff8bab7d9c91625ece1c444700&amp;idx=4&amp;mid=2247582158&amp;sn=00c0d1581aefd144d102083c59ecd95d" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="百度发布文心5-5-flash-11月25日开源" tabindex="-1"><a class="header-anchor" href="#百度发布文心5-5-flash-11月25日开源"><span>百度发布文心5.5 Flash，11月25日开源</span></a></h3><p>百度发布文心 5.5 Flash Preview，总参数 2800 亿但每次仅激活 140 亿，定于 11 月 25 日开源。模型现已上线千帆 API，限时五折后百万 token 输入闲时 0.5 元。</p><p>推理效率：每秒超200 token，靠摘要压缩与草稿机制提速</p><p>长程代码：纯文本输入下连续运行11小时写出虚幻5游戏<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f02d8bb553c6327d767b283f832099c9d6e00f284da9d9331f3414633eb0c4e7295a67d03bfc&amp;idx=2&amp;mid=2652742286&amp;sn=c52effcf422a1c9f2503cbf18ffe0d8d" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="英伟达开源-nemotron-3-5-语音模型" tabindex="-1"><a class="header-anchor" href="#英伟达开源-nemotron-3-5-语音模型"><span>英伟达开源 Nemotron 3.5 语音模型</span></a></h3><p>英伟达开源多功能语音模型 Nemotron 3.5 Transcribe，支持通过指令生成逐字稿、翻译及音频问答，覆盖 40 种语言，最长可处理约 1 小时录音。</p><p>Mamba-2与Transformer混合，激活4.3B参数</p><p>场景：面向离线音频处理，支持说话人标注<a href="https://mp.weixin.qq.com/s?__biz=MzU3NTQ2NDIyOQ==&amp;chksm=fcc18349a588e90e53d802595f41a18be28096e4daa9fabbe3a5577a1d611d8ef511a9e07b1e&amp;idx=1&amp;mid=2247531343&amp;sn=1d880dc550f53777cab86db1784b9b3b" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="openjiuwen-开源-hyperagent-架构" tabindex="-1"><a class="header-anchor" href="#openjiuwen-开源-hyperagent-架构"><span>openJiuwen 开源 HyperAgent 架构</span></a></h3><p>openJiuwen 解读 HyperAgent 架构，提出 Agent 需从单次响应转向 持续承担工作的智能主体，并开源支持跨会话协作与自主演进的 AgentOS 分层设计。</p><p>永续协作：摆脱单次会话限制，跨渠道协作并保留长期记忆</p><p>协同演进：通过 CoRSI 机制让产物、框架与模型递归改进</p><p>部署适配：支持从个人单机到企业分布式集群两类场景<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=85481f95e4279255c08258381b3bf9aff189bbaf030491d8f8472fbc769cee3cdafbe87f7a8e&amp;idx=2&amp;mid=2651073583&amp;sn=b51e6ed1e5957fa9dffb517b737cd2c1" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="算法论文" tabindex="-1"><a class="header-anchor" href="#算法论文"><span>算法论文</span></a></h2><h3 id="姚期智团队提出awm-让ai用数学证明无解" tabindex="-1"><a class="header-anchor" href="#姚期智团队提出awm-让ai用数学证明无解"><span>姚期智团队提出AWM：让AI用数学证明无解</span></a></h3><p>清华姚期智团队提出代数世界模型（AWM），让 AI 探索陌生环境规律，并用 Lean 4 严格证明任务无解。在 ARC-AGI-3 关卡中全部构造出可独立检查的封闭证明。</p><p>原理：通过三阶段探索环境并在Lean中形式化建模</p><p>效率：认证获胜轨迹仅用人类基线43%的行动次数<a href="https://mp.weixin.qq.com/s?__biz=MzI1MjQ2OTQ3Ng==&amp;chksm=e82f1e8bcb218c6bd9d898d3f6554efe52c4739c85cdaef4ff55faf6850560647dbf3328441a&amp;idx=1&amp;mid=2247668578&amp;sn=ddffb2bead584135d76f9cf1bc593f7c" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="anthropic公开claude长期记忆架构" tabindex="-1"><a class="header-anchor" href="#anthropic公开claude长期记忆架构"><span>Anthropic公开Claude长期记忆架构</span></a></h3><p>Anthropic 公开 Claude 长期记忆设计，提出四层记忆模型与离线整理机制。这套方案已用于 Claude Code，通过对照原始底账定期纠错，解决经验丢失与错误继承问题。</p><p>分层设计：从无损原始流水提炼为笔记、Wiki与顶层索引</p><p>离线纠错：调取原始执行记录，重写曾误导后续会话的错误笔记</p><p>落地方案：Claude Code开局仅读取前200行或25KB索引<a href="https://mp.weixin.qq.com/s?__biz=Mzk0OTI1OTQ2MQ==&amp;chksm=c26403e240a8ed8c38b465afc50f06c26a3840a18373be9a08167ac51cd7a549154581685037&amp;idx=1&amp;mid=2247601894&amp;sn=359af22565ec139139bf39d53cff20e9" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><p style="text-align:center;"><img id="weixin_qr" src="https://meikan-public-images.oss-cn-beijing.aliyuncs.com/imeikan/assets/2025-05-18234303-hub.png" style="max-width:800px;object-fit:cover;"></p><p><a href="https://aireadinghub.com/" target="_blank" rel="noopener noreferrer">官网：www.AiReadingHub.com</a></p>',105)]))}const t=a(i,[["render",d]]),s=JSON.parse('{"path":"/posts/2026-11-12.html","title":"AI日报：芯片厂商Cerebras上市半年股价跌77%; 菜鸟开放仓库训练机器人，推出海三日达; 张一鸣称字节追上OpenAI至少到2029年","lang":"zh-CN","frontmatter":{"date":"2026-11-12T00:00:00.000Z","title":"AI日报：芯片厂商Cerebras上市半年股价跌77%; 菜鸟开放仓库训练机器人，推出海三日达; 张一鸣称字节追上OpenAI至少到2029年"},"headers":[{"level":2,"title":"新闻资讯","slug":"新闻资讯","link":"#新闻资讯","children":[{"level":3,"title":"芯片厂商Cerebras上市半年股价跌77%","slug":"芯片厂商cerebras上市半年股价跌77","link":"#芯片厂商cerebras上市半年股价跌77","children":[]},{"level":3,"title":"菜鸟开放仓库训练机器人，推出海三日达","slug":"菜鸟开放仓库训练机器人-推出海三日达","link":"#菜鸟开放仓库训练机器人-推出海三日达","children":[]},{"level":3,"title":"张一鸣称字节追上OpenAI至少到2029年","slug":"张一鸣称字节追上openai至少到2029年","link":"#张一鸣称字节追上openai至少到2029年","children":[]},{"level":3,"title":"AI数据公司Mercor估值达200亿美元","slug":"ai数据公司mercor估值达200亿美元","link":"#ai数据公司mercor估值达200亿美元","children":[]},{"level":3,"title":"科技报告：美工程师招聘腰斩PM增56%","slug":"科技报告-美工程师招聘腰斩pm增56","link":"#科技报告-美工程师招聘腰斩pm增56","children":[]},{"level":3,"title":"Claude 仅用 3 天自主移植 AMD 芯片内核","slug":"claude-仅用-3-天自主移植-amd-芯片内核","link":"#claude-仅用-3-天自主移植-amd-芯片内核","children":[]},{"level":3,"title":"阿里分拆芯片业务平头哥拟赴港上市","slug":"阿里分拆芯片业务平头哥拟赴港上市","link":"#阿里分拆芯片业务平头哥拟赴港上市","children":[]}]},{"level":2,"title":"产品应用","slug":"产品应用","link":"#产品应用","children":[{"level":3,"title":"Claude Fable 5.2提示词指南发布","slug":"claude-fable-5-2提示词指南发布","link":"#claude-fable-5-2提示词指南发布","children":[]},{"level":3,"title":"腾讯上线元宝搜索并开放独立网页","slug":"腾讯上线元宝搜索并开放独立网页","link":"#腾讯上线元宝搜索并开放独立网页","children":[]},{"level":3,"title":"谷歌发布决策模型，百万输入 0.1 美元","slug":"谷歌发布决策模型-百万输入-0-1-美元","link":"#谷歌发布决策模型-百万输入-0-1-美元","children":[]},{"level":3,"title":"即梦上线短剧工作室：视频每秒最低0.16元","slug":"即梦上线短剧工作室-视频每秒最低0-16元","link":"#即梦上线短剧工作室-视频每秒最低0-16元","children":[]},{"level":3,"title":"腾讯发布Buddy One打通全家桶AI","slug":"腾讯发布buddy-one打通全家桶ai","link":"#腾讯发布buddy-one打通全家桶ai","children":[]}]},{"level":2,"title":"推荐文章","slug":"推荐文章","link":"#推荐文章","children":[{"level":3,"title":"前Meta工程师称AI写代码让系统变脆","slug":"前meta工程师称ai写代码让系统变脆","link":"#前meta工程师称ai写代码让系统变脆","children":[]}]},{"level":2,"title":"开源动态","slug":"开源动态","link":"#开源动态","children":[{"level":3,"title":"MiniMax开源H3-Image，10秒出4K图","slug":"minimax开源h3-image-10秒出4k图","link":"#minimax开源h3-image-10秒出4k图","children":[]},{"level":3,"title":"vLLM 与 SGLang 追平 DeepInfer 性能","slug":"vllm-与-sglang-追平-deepinfer-性能","link":"#vllm-与-sglang-追平-deepinfer-性能","children":[]},{"level":3,"title":"百度发布文心5.5 Flash，11月25日开源","slug":"百度发布文心5-5-flash-11月25日开源","link":"#百度发布文心5-5-flash-11月25日开源","children":[]},{"level":3,"title":"英伟达开源 Nemotron 3.5 语音模型","slug":"英伟达开源-nemotron-3-5-语音模型","link":"#英伟达开源-nemotron-3-5-语音模型","children":[]},{"level":3,"title":"openJiuwen 开源 HyperAgent 架构","slug":"openjiuwen-开源-hyperagent-架构","link":"#openjiuwen-开源-hyperagent-架构","children":[]}]},{"level":2,"title":"算法论文","slug":"算法论文","link":"#算法论文","children":[{"level":3,"title":"姚期智团队提出AWM：让AI用数学证明无解","slug":"姚期智团队提出awm-让ai用数学证明无解","link":"#姚期智团队提出awm-让ai用数学证明无解","children":[]},{"level":3,"title":"Anthropic公开Claude长期记忆架构","slug":"anthropic公开claude长期记忆架构","link":"#anthropic公开claude长期记忆架构","children":[]}]}],"git":{"updatedTime":1794570626000,"contributors":[{"name":"GitHub Actions","username":"","email":"actions@github.com","commits":1}],"changelog":[{"hash":"61fc0e1cc02aace62bd7844b0d5dff0eb8081f42","time":1794570626000,"email":"actions@github.com","author":"GitHub Actions","message":"Auto-commit generated files on 2026-11-13T11:50:26.949Z"}]},"filePathRelative":"posts/2026-11-12.md","excerpt":"<blockquote>\\n<p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。\\n欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p>\\n</blockquote>\\n<h1>2026-11-12 资讯日报</h1>\\n<h2>新闻资讯</h2>\\n<h3>芯片厂商Cerebras上市半年股价跌77%</h3>\\n<p>芯片公司 Cerebras 上市半年股价暴跌近77%。其核心硬件销售连续两季下滑，云服务占比升至70%，二季度现金流出达营收的2.65倍。</p>\\n<p>云服务收入占比升至70%，硬件销售连续两季下滑</p>"}');export{t as comp,s as data};
